@namespace sv_30df1d57ff4e440198da12e941616222.Components.Pages.Apply

<div class="reference-form">
    <h4>Reference @(Index + 1)</h4>

    @if (ShowRemove)
    {
        <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
    }

    <div class="form-row">
        <div class="form-group">
            <label>Name <span class="required">*</span></label>
            <input type="text" value="@Name" @oninput="e => { Name = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" class="form-control" />
        </div>
        <div class="form-group">
            <label>Relationship <span class="required">*</span></label>
            <input type="text" value="@Relationship" @oninput="e => { Relationship = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Email <span class="required">*</span></label>
            <input type="email" value="@Email" @oninput="e => { Email = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" class="form-control" />
        </div>
        <div class="form-group">
            <label>Phone <span class="required">*</span></label>
            <input type="tel" value="@Phone" @oninput="e => { Phone = e.Value?.ToString() ?? \"\"; NotifyChanged(); }" class="form-control" />
        </div>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Name { get; set; } = "";
    [Parameter] public string Relationship { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<ReferenceData> OnChanged { get; set; }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new ReferenceData(Name, Relationship, Email, Phone));
    }

    public record ReferenceData(string Name, string Relationship, string Email, string Phone);
}

@namespace sv_30df1d57ff4e440198da12e941616222.Components.Pages.Apply

<div class="step-form references-step">
    <h2>References</h2>

    @for (int i = 0; i < _references.Count; i++)
    {
        var index = i;
        var r = _references[index];
        <ReferenceForm Index="index"
                       Name="@r.Name"
                       Relationship="@r.Relationship"
                       Email="@r.Email"
                       Phone="@r.Phone"
                       ShowRemove="@(_references.Count > 2)"
                       OnRemove="() => RemoveReference(index)"
                       OnChanged="data => UpdateReference(index, data)" />
    }

    @if (_references.Count < 3)
    {
        <button class="btn btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="validation-summary">@_validationError</div>
    }

    <div class="step-actions">
        <button class="btn btn-outline" @onclick="HandleBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceState>? References { get; set; }
    [Parameter] public EventCallback<List<ReferenceState>> OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private List<ReferenceState> _references = new();
    private string? _validationError;

    protected override void OnParametersSet()
    {
        if (References is not null && References.Count > 0)
        {
            _references = References.Select(r => r with { }).ToList();
        }
        else if (_references.Count == 0)
        {
            _references.Add(new ReferenceState());
            _references.Add(new ReferenceState());
        }
    }

    private void AddReference()
    {
        if (_references.Count < 3)
            _references.Add(new ReferenceState());
    }

    private void RemoveReference(int index)
    {
        if (_references.Count > 2)
            _references.RemoveAt(index);
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        _references[index] = new ReferenceState
        {
            Name = data.Name,
            Relationship = data.Relationship,
            Email = data.Email,
            Phone = data.Phone
        };
    }

    private async Task HandleNext()
    {
        _validationError = null;
        foreach (var r in _references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync(_references);
    }

    private async Task HandleBack() => await OnBack.InvokeAsync();

    public record ReferenceState
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

