@page "/apply"
@namespace sv_30df1d57ff4e440198da12e941616222.Components.Pages.Apply
@using sv_30df1d57ff4e440198da12e941616222.Models
@using sv_30df1d57ff4e440198da12e941616222.Services
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="apply-page">
    <h1>Job Application</h1>

    <StepIndicator CurrentStep="_currentStep"
                   CompletedSteps="_completedSteps"
                   OnStepSelected="GoToStep" />

    <div class="step-content">
        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep FullName="@_fullName"
                                  Email="@_email"
                                  Phone="@_phone"
                                  Address="@_address"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync"
                                  OnNext="HandlePersonalNext" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnNext="HandleWorkNext"
                                 OnBack="GoBack" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                OnNext="HandleReferencesNext"
                                OnBack="GoBack" />
                break;

            case 3:
                <CoverLetterStep Text="@_coverLetter"
                                 OnNext="HandleCoverLetterNext"
                                 OnBack="GoBack" />
                break;

            case 4:
                <ReviewStep Personal="@GetPersonalInfo()"
                            WorkEntries="_workEntries"
                            References="_references"
                            CoverLetter="@_coverLetter"
                            OnEditSection="GoToStep"
                            OnBack="GoBack"
                            OnSubmit="SubmitApplication" />
                break;
        }
    </div>
</div>

@code {
    private int _currentStep;
    private HashSet<int> _completedSteps = new();

    // Step 1 state
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";

    // Step 2 state
    private List<WorkHistoryStep.WorkEntryState> _workEntries = new();

    // Step 3 state
    private List<ReferencesStep.ReferenceState> _references = new();

    // Step 4 state
    private string _coverLetter = "";

    private void GoToStep(int step)
    {
        _currentStep = step;
    }

    private void GoBack()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private void HandlePersonalNext((string FullName, string Email, string Phone, string Address) data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _completedSteps.Add(0);
        _currentStep = 1;
    }

    private void HandleWorkNext(List<WorkHistoryStep.WorkEntryState> entries)
    {
        _workEntries = entries;
        _completedSteps.Add(1);
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceState> refs)
    {
        _references = refs;
        _completedSteps.Add(2);
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string text)
    {
        _coverLetter = text;
        _completedSteps.Add(3);
        _currentStep = 4;
    }

    private PersonalInfo GetPersonalInfo() => new(_fullName, _email, _phone, _address);

    private async Task<int> SubmitApplication()
    {
        var workHistory = new WorkHistory(_workEntries.Select(e =>
            new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.EndDate, e.Description)).ToList());

        var references = _references.Select(r =>
            new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();

        var application = new JobApplication(GetPersonalInfo(), workHistory, references, _coverLetter);
        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.apply-page {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem 1rem;
}

.apply-page h1 {
    text-align: center;
    margin-bottom: 2rem;
}

/* Step Indicator */
.step-indicator {
    margin-bottom: 2rem;
}

.step-list {
    display: flex;
    list-style: none;
    padding: 0;
    margin: 0;
    justify-content: space-between;
}

.step-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
    cursor: default;
    position: relative;
}

.step-item.completed {
    cursor: pointer;
}

.step-badge {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.5rem;
    border: 2px solid #ccc;
    background: #fff;
    color: #999;
    transition: all 0.2s;
}

.step-item.active .step-badge {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step-item.completed .step-badge {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.8rem;
    text-align: center;
    color: #999;
}

.step-item.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step-item.completed .step-label {
    color: #198754;
}

.checkmark {
    font-size: 1rem;
}

/* Step Content */
.step-content {
    background: #fff;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 2rem;
}

.step-form h2 {
    margin-bottom: 1.5rem;
    color: #333;
}

/* Form Controls */
.form-group {
    margin-bottom: 1rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.3rem;
    font-weight: 500;
    color: #555;
}

.form-control {
    width: 100%;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ced4da;
    border-radius: 4px;
    font-size: 1rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-control:focus {
    border-color: #0d6efd;
    outline: none;
    box-shadow: 0 0 0 2px rgba(13, 110, 253, 0.15);
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.required {
    color: #dc3545;
}

.field-error {
    color: #dc3545;
    font-size: 0.85rem;
    margin-top: 0.25rem;
    display: block;
}

.validation-summary {
    background: #f8d7da;
    color: #842029;
    border: 1px solid #f5c2c7;
    border-radius: 4px;
    padding: 0.75rem 1rem;
    margin: 1rem 0;
}

/* Buttons */
.step-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1rem;
    border-top: 1px solid #eee;
}

.btn {
    padding: 0.6rem 1.5rem;
    border-radius: 4px;
    font-size: 1rem;
    cursor: pointer;
    border: none;
    transition: background 0.2s;
}

.btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

.btn-primary {
    background: #0d6efd;
    color: #fff;
}

.btn-primary:hover:not(:disabled) {
    background: #0b5ed7;
}

.btn-outline {
    background: #fff;
    color: #0d6efd;
    border: 1px solid #0d6efd;
}

.btn-outline:hover {
    background: #e7f1ff;
}

.btn-secondary {
    background: #6c757d;
    color: #fff;
}

.btn-secondary:hover {
    background: #5c636a;
}

.btn-danger {
    background: #dc3545;
    color: #fff;
}

.btn-sm {
    padding: 0.3rem 0.8rem;
    font-size: 0.85rem;
}

.btn-link {
    background: none;
    border: none;
    color: #0d6efd;
    cursor: pointer;
    text-decoration: underline;
    font-size: 0.9rem;
    padding: 0;
}

.btn-link:hover {
    color: #0b5ed7;
}

.btn-submit {
    padding: 0.75rem 2rem;
    font-size: 1.1rem;
}

/* Work Entry Form */
.work-entry-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.entry-header h4 {
    margin: 0;
}

.checkbox-label {
    display: inline-flex !important;
    align-items: center;
    gap: 0.4rem;
    margin-top: 0.4rem;
    font-weight: normal !important;
    cursor: pointer;
}

/* Reference Form */
.reference-form {
    border: 1px solid #e9ecef;
    border-radius: 6px;
    padding: 1.25rem;
    margin-bottom: 1rem;
    background: #f8f9fa;
}

.reference-form h4 {
    margin: 0 0 1rem 0;
}

/* Cover Letter */
.cover-letter-textarea {
    resize: vertical;
    min-height: 200px;
}

.char-count {
    text-align: right;
    font-size: 0.85rem;
    color: #6c757d;
    margin-top: 0.3rem;
}

/* Review Step */
.review-section {
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
    border-bottom: 1px solid #eee;
}

.review-section:last-of-type {
    border-bottom: none;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.75rem;
}

.section-header h3 {
    margin: 0;
    font-size: 1.1rem;
}

.review-section dl {
    display: grid;
    grid-template-columns: 120px 1fr;
    gap: 0.3rem 1rem;
    margin: 0;
}

.review-section dt {
    font-weight: 600;
    color: #555;
}

.review-section dd {
    margin: 0;
}

.review-entry {
    margin-bottom: 0.75rem;
    padding-left: 0.5rem;
    border-left: 3px solid #dee2e6;
}

.date-range {
    font-size: 0.9rem;
    color: #6c757d;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f8f9fa;
    padding: 1rem;
    border-radius: 4px;
    max-height: 200px;
    overflow-y: auto;
}

/* Confirmation */
.confirmation {
    text-align: center;
    padding: 2rem;
}

.confirmation h3 {
    color: #198754;
    font-size: 1.5rem;
}

@media (max-width: 600px) {
    .step-list {
        flex-wrap: wrap;
        gap: 0.5rem;
    }

    .form-row {
        grid-template-columns: 1fr;
    }

    .step-label {
        font-size: 0.7rem;
    }
}

