@namespace sv_30df1d57ff4e440198da12e941616222.Components.Pages.Apply

<div class="work-entry-form">
    <div class="entry-header">
        <h4>Position @(Index + 1)</h4>
        @if (ShowRemove)
        {
            <button class="btn btn-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
        }
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Company Name <span class="required">*</span></label>
            <input type="text" value="@Company" @oninput="OnCompanyInput" class="form-control" />
        </div>
        <div class="form-group">
            <label>Job Title <span class="required">*</span></label>
            <input type="text" value="@Title" @oninput="OnTitleInput" class="form-control" />
        </div>
    </div>

    <div class="form-row">
        <div class="form-group">
            <label>Start Date <span class="required">*</span></label>
            <input type="date" value="@FormatDate(StartDate)" @onchange="OnStartDateChange" class="form-control" />
        </div>
        <div class="form-group">
            <label>End Date</label>
            <input type="date" value="@FormatDate(EndDate)" @onchange="OnEndDateChange" class="form-control" disabled="@IsCurrent" />
            <label class="checkbox-label">
                <input type="checkbox" checked="@IsCurrent" @onchange="OnIsCurrentChange" />
                Currently working here
            </label>
        </div>
    </div>

    <div class="form-group">
        <label>Description</label>
        <textarea value="@Description" @oninput="OnDescriptionInput" class="form-control" rows="3"></textarea>
    </div>
</div>

@code {
    [Parameter] public int Index { get; set; }
    [Parameter] public string Company { get; set; } = "";
    [Parameter] public string Title { get; set; } = "";
    [Parameter] public DateTime? StartDate { get; set; }
    [Parameter] public DateTime? EndDate { get; set; }
    [Parameter] public bool IsCurrent { get; set; }
    [Parameter] public string Description { get; set; } = "";
    [Parameter] public bool ShowRemove { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }
    [Parameter] public EventCallback<WorkEntryData> OnChanged { get; set; }

    private string FormatDate(DateTime? date) => date?.ToString("yyyy-MM-dd") ?? "";

    private void OnCompanyInput(ChangeEventArgs e) { Company = e.Value?.ToString() ?? ""; NotifyChanged(); }
    private void OnTitleInput(ChangeEventArgs e) { Title = e.Value?.ToString() ?? ""; NotifyChanged(); }
    private void OnDescriptionInput(ChangeEventArgs e) { Description = e.Value?.ToString() ?? ""; NotifyChanged(); }

    private void OnStartDateChange(ChangeEventArgs e)
    {
        StartDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        NotifyChanged();
    }

    private void OnEndDateChange(ChangeEventArgs e)
    {
        EndDate = DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null;
        NotifyChanged();
    }

    private void OnIsCurrentChange(ChangeEventArgs e)
    {
        IsCurrent = (bool)(e.Value ?? false);
        if (IsCurrent) EndDate = null;
        NotifyChanged();
    }

    private void NotifyChanged()
    {
        OnChanged.InvokeAsync(new WorkEntryData(Company, Title, StartDate, EndDate, IsCurrent, Description));
    }

    public record WorkEntryData(string Company, string Title, DateTime? StartDate, DateTime? EndDate, bool IsCurrent, string Description);
}

